import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 16 .b8 dyn_smem[];
// Cooperative tiled transposed 3D convolution (specialized for k=3,
// stride=1, padding=0, groups=1, cubic volumes).
// Register blocking over output channels: each CTA computes one 8x8x4
// (D x H x W) output tile for FOUR consecutive output channels of one
// batch element. For every input channel the 10x10x6 input halo region
// is staged into shared memory (out-of-bounds halo slots are zero-filled
// once up front) and the 4x27 weights of the current (oc0..oc0+3, ic)
// slice are staged into shared memory in transposed [tap][oc] order
// (16-byte aligned). Each of the 256 threads then computes four output
// elements with a fully unrolled 27-tap pass in which one scalar shared
// activation load plus one vectorized v4 shared weight load feed four
// FMAs, cutting shared-memory load instructions roughly 4x versus the
// one-output-channel-per-CTA version.
.visible .entry conv_transpose3d_fwd(
    .param .u64 _in_ptr,
    .param .u64 _w_ptr,
    .param .u64 _out_ptr,
    .param .u32 _total,
    .param .u32 _ic,
    .param .u32 _oc,
    .param .u32 _inD,
    .param .u32 _outD,
    .param .u32 _k
)
{
    .reg .pred  %p<8>;
    .reg .b32   %r<64>;
    .reg .b64   %rd<8>;
    .reg .f32   %f<16>;
    ld.param.u64 %rd0, [_in_ptr];
    ld.param.u64 %rd1, [_w_ptr];
    ld.param.u64 %rd2, [_out_ptr];
    ld.param.u32 %r8,  [_ic];
    ld.param.u32 %r9,  [_oc];
    ld.param.u32 %r10, [_inD];
    ld.param.u32 %r11, [_outD];
    // tile counts: TW = ceil(outW/4), TH = TD = ceil(outD/8)
    add.u32 %r2, %r11, 3;
    shr.u32 %r2, %r2, 2;
    add.u32 %r5, %r11, 7;
    shr.u32 %r5, %r5, 3;
    shr.u32 %r49, %r9, 2;               // OCB = OC/4 output-channel blocks
    // decode ctaid -> (n, ocb, td, th, tw), tw fastest
    mov.u32 %r1, %ctaid.x;
    rem.u32 %r3, %r1, %r2;
    div.u32 %r4, %r1, %r2;
    rem.u32 %r6, %r4, %r5;
    div.u32 %r4, %r4, %r5;
    rem.u32 %r7, %r4, %r5;
    div.u32 %r4, %r4, %r5;
    rem.u32 %r30, %r4, %r49;            // oc block index
    div.u32 %r31, %r4, %r49;            // n
    shl.b32 %r30, %r30, 2;              // oc0 = oc block * 4
    shl.b32 %r13, %r7, 3;               // base_d = td*8
    shl.b32 %r14, %r6, 3;               // base_h = th*8
    shl.b32 %r15, %r3, 2;               // base_w = tw*4
    // thread -> output element inside the 8x8x4 tile
    mov.u32 %r16, %tid.x;
    and.b32 %r17, %r16, 3;              // w_l = tid % 4
    shr.u32 %r18, %r16, 2;
    and.b32 %r18, %r18, 7;              // h_l = (tid/4) % 8
    shr.u32 %r19, %r16, 5;              // d_l = tid/32
    add.u32 %r36, %r13, %r19;           // od
    add.u32 %r37, %r14, %r18;           // oh
    add.u32 %r38, %r15, %r17;           // ow
    mul.lo.u32 %r28, %r10, %r10;        // inD^2
    mul.lo.u32 %r29, %r28, %r10;        // inD^3
    mul.lo.u32 %r44, %r11, %r11;        // outD^2
    // input channel base byte pointer for ic = 0: in + n*IC*inD^3*4
    mul.lo.u32 %r40, %r31, %r8;
    mul.wide.u32 %rd5, %r40, %r29;
    shl.b64 %rd5, %rd5, 2;
    add.u64 %rd3, %rd0, %rd5;           // cur input base ptr
    mul.wide.u32 %rd6, %r29, 4;         // per-ic byte increment
    // weight base byte pointer for ic = 0: w + oc0*27*4
    mul.wide.u32 %rd5, %r30, 108;
    add.u64 %rd4, %rd1, %rd5;           // cur weight base ptr
    mul.wide.u32 %rd7, %r9, 108;        // per-ic byte increment (OC*27*4)
    // shared memory base
    mov.u32 %r32, dyn_smem;
    // per-thread smem read base: (d_l*60 + h_l*6 + w_l)*4
    mul.lo.u32 %r33, %r19, 60;
    mad.lo.u32 %r33, %r18, 6, %r33;
    add.u32 %r33, %r33, %r17;
    mul.lo.u32 %r33, %r33, 4;
    add.u32 %r34, %r32, %r33;
    // shared weight base after the 600-float input halo: dyn_smem + 2400
    add.u32 %r63, %r32, 2400;
    // ---------- setup cooperative load slots (li = tid + 256*round) --------
    // round 0: li = tid (always valid)
    mov.u32 %r20, %r16;
    rem.u32 %r21, %r20, 6;
    div.u32 %r22, %r20, 6;
    rem.u32 %r23, %r22, 10;
    div.u32 %r24, %r22, 10;
    add.s32 %r25, %r15, %r21;
    sub.s32 %r25, %r25, 2;              // gx
    add.s32 %r26, %r14, %r23;
    sub.s32 %r26, %r26, 2;              // gy
    add.s32 %r27, %r13, %r24;
    sub.s32 %r27, %r27, 2;              // gz
    mul.lo.u32 %r54, %r27, %r28;
    mad.lo.u32 %r54, %r26, %r10, %r54;
    add.u32 %r54, %r54, %r25;           // element offset (valid if in bounds)
    mul.lo.u32 %r57, %r20, 4;
    add.u32 %r57, %r32, %r57;           // smem byte addr
    setp.lt.s32 %p1, %r25, 0;
    setp.ge.s32 %p2, %r25, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r26, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r26, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r27, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r27, %r10;
    or.pred %p1, %p1, %p2;
    selp.u32 %r60, 0, 1, %p1;           // 1 = in bounds, 0 = halo
    mov.f32 %f3, 0f00000000;
    @%p1 st.shared.f32 [%r57], %f3;     // zero-fill halo slot once
    // round 1: li = tid + 256 (always < 600)
    add.u32 %r20, %r16, 256;
    rem.u32 %r21, %r20, 6;
    div.u32 %r22, %r20, 6;
    rem.u32 %r23, %r22, 10;
    div.u32 %r24, %r22, 10;
    add.s32 %r25, %r15, %r21;
    sub.s32 %r25, %r25, 2;
    add.s32 %r26, %r14, %r23;
    sub.s32 %r26, %r26, 2;
    add.s32 %r27, %r13, %r24;
    sub.s32 %r27, %r27, 2;
    mul.lo.u32 %r55, %r27, %r28;
    mad.lo.u32 %r55, %r26, %r10, %r55;
    add.u32 %r55, %r55, %r25;
    mul.lo.u32 %r58, %r20, 4;
    add.u32 %r58, %r32, %r58;
    setp.lt.s32 %p1, %r25, 0;
    setp.ge.s32 %p2, %r25, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r26, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r26, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r27, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r27, %r10;
    or.pred %p1, %p1, %p2;
    selp.u32 %r61, 0, 1, %p1;
    @%p1 st.shared.f32 [%r58], %f3;
    // round 2: li = tid + 512, only tid < 88
    setp.lt.u32 %p3, %r16, 88;
    @!%p3 bra L_SETUP_DONE;
    add.u32 %r20, %r16, 512;
    rem.u32 %r21, %r20, 6;
    div.u32 %r22, %r20, 6;
    rem.u32 %r23, %r22, 10;
    div.u32 %r24, %r22, 10;
    add.s32 %r25, %r15, %r21;
    sub.s32 %r25, %r25, 2;
    add.s32 %r26, %r14, %r23;
    sub.s32 %r26, %r26, 2;
    add.s32 %r27, %r13, %r24;
    sub.s32 %r27, %r27, 2;
    mul.lo.u32 %r56, %r27, %r28;
    mad.lo.u32 %r56, %r26, %r10, %r56;
    add.u32 %r56, %r56, %r25;
    mul.lo.u32 %r59, %r20, 4;
    add.u32 %r59, %r32, %r59;
    setp.lt.s32 %p1, %r25, 0;
    setp.ge.s32 %p2, %r25, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r26, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r26, %r10;
    or.pred %p1, %p1, %p2;
    setp.lt.s32 %p2, %r27, 0;
    or.pred %p1, %p1, %p2;
    setp.ge.s32 %p2, %r27, %r10;
    or.pred %p1, %p1, %p2;
    selp.u32 %r62, 0, 1, %p1;
    @%p1 st.shared.f32 [%r59], %f3;
L_SETUP_DONE:
    mov.f32 %f0, 0f00000000;            // accumulator oc0
    mov.f32 %f8, 0f00000000;            // accumulator oc1
    mov.f32 %f9, 0f00000000;            // accumulator oc2
    mov.f32 %f10, 0f00000000;           // accumulator oc3
    mov.u32 %r35, 0;                    // ic loop counter
L_IC_LOOP:
    setp.ge.u32 %p0, %r35, %r8;
    @%p0 bra L_IC_DONE;
    // ---- stage current input channel halo into shared memory ----
    setp.eq.u32 %p1, %r60, 0;
    @%p1 bra L_SKIP0;
    mul.wide.u32 %rd5, %r54, 4;
    add.u64 %rd5, %rd3, %rd5;
    ld.global.f32 %f3, [%rd5];
    st.shared.f32 [%r57], %f3;
L_SKIP0:
    setp.eq.u32 %p1, %r61, 0;
    @%p1 bra L_SKIP1;
    mul.wide.u32 %rd5, %r55, 4;
    add.u64 %rd5, %rd3, %rd5;
    ld.global.f32 %f3, [%rd5];
    st.shared.f32 [%r58], %f3;
L_SKIP1:
    setp.lt.u32 %p3, %r16, 88;
    @!%p3 bra L_LOAD_DONE;
    setp.eq.u32 %p1, %r62, 0;
    @%p1 bra L_LOAD_DONE;
    mul.wide.u32 %rd5, %r56, 4;
    add.u64 %rd5, %rd3, %rd5;
    ld.global.f32 %f3, [%rd5];
    st.shared.f32 [%r59], %f3;
L_LOAD_DONE:
    // ---- stage the 4x27 (oc0..oc0+3, ic) weights transposed [tap][oc] ----
    setp.lt.u32 %p4, %r16, 108;
    @!%p4 bra L_W_DONE;
    and.b32 %r50, %r16, 3;              // j = tid % 4 (oc lane)
    shr.u32 %r51, %r16, 2;              // t = tid / 4 (tap index)
    mul.lo.u32 %r52, %r50, 27;
    add.u32 %r52, %r52, %r51;           // weight element j*27 + t
    mul.wide.u32 %rd5, %r52, 4;
    add.u64 %rd5, %rd4, %rd5;
    ld.global.f32 %f3, [%rd5];
    shl.b32 %r53, %r16, 2;              // smem slot (t*4 + j)*4 == tid*4
    add.u32 %r53, %r63, %r53;
    st.shared.f32 [%r53], %f3;
L_W_DONE:
    bar.sync 0;
    // ---- 27-tap unrolled pass: 1 act load + 1 v4 weight load -> 4 FMAs ----
    ld.shared.f32 %f1, [%r34+536];
    ld.shared.v4.f32 {%f4,%f5,%f6,%f7}, [%r63];
    fma.rn.f32 %f0, %f1, %f4, %f0;
    fma.rn.f32 %f8, %f1, %f5, %f8;
    fma.rn.f32 %f9, %f1, %f6, %f9;
    fma.rn.f32 %f10, %f1, %f7, %f10;
    ld.shared.f32 %f1, [%r34+532];
    ld.shared.v4.f32 {%f4,%f5,%f6,%f7}, [%r63+16];
    fma.rn.f32 %f0, %f1, %f4, %f0;
    fma.rn.f32 %f8, %f1, %f5, %f8;
    fma.rn.f32 %f9, %f1, %f6, %f9;
    fma.rn.f32 %f10, %f1, %f7, %f10;
    ld.shared.f32 %f1, [%r34+528];
    ld.shared.v4.f32 {%f4,%f5,%f6,%f7}, [%r63+32];
    fma.rn.f32 %f0, %f1, %f4, %f0;
